const raw = $input.first().json || {};
let item = raw;

// AI Agent passes tool arguments as 'query' (sometimes JSON string)
if (raw.query) {
  if (typeof raw.query === 'string') {
    try {
      item = JSON.parse(raw.query);
    } catch (e) {
      item = raw;
    }
  } else if (typeof raw.query === 'object') {
    item = raw.query;
  }
}

// Build clean payload
const payload = {};

const to = item.to || item.recipient_email || item.to_email || '';
const from_addr = item.from || item.from_email || 'me';
const subject = item.subject || item.email_subject || '';
const html = item.html || item.body || item.text || item.content || '<p>No content</p>';

if (!to) throw new Error('Missing required field: to');
if (!subject) throw new Error('Missing required field: subject');

payload.to = to;
payload.from = from_addr;
payload.subject = subject;
payload.html = html;

const cc = item.cc || item.cc_emails || [];
if (cc && (Array.isArray(cc) ? cc.length > 0 : String(cc).trim().length > 0)) {
  payload.cc = cc;
}

return [{ json: payload }];
